1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Locale;
5	import java.util.Set;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Assigns the {@code customerCode} formatted {@code <REGION>-<HASH8>}, where REGION is the region
13	 * code derived from the owner's postcode (see {@link Locality}, which prefers the postcode's range,
14	 * falling back to the city table and finally {@code "UNKNOWN"}) and HASH8 is the first 8 upper-case
15	 * hex characters of SHA-256 over the normalized telephone concatenated with the last name (e.g.
16	 * {@code NSW-1A2B3C4D}). The telephone has already been normalized to E.164 form by
17	 * {@link NormalizeTelephone} earlier in the pipeline, so the stored value is used directly.
18	 * <p>
19	 * When the computed code collides with an existing owner's {@code customerCode}, {@code -<n>} is
20	 * appended with the smallest {@code n} of 2 or more that makes it unique (e.g. {@code NSW-1A2B3C4D-2}).
21	 * Runs before the owner is saved, so {@link OwnerRepository#findAll()} sees only the owners that
22	 * existed before this create.
23	 */
24	public class AssignCustomerCode {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String region = Locality.of(owner.getCity(), owner.getPostcode());
28	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
29	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
30	        String hash8 = Sha256.hex(telephone + lastName).substring(0, 8).toUpperCase(Locale.ROOT);
31	        String base = region + "-" + hash8;
32	
33	        Set<String> existing = new HashSet<>();
34	        for (Owner other : ownerRepository.findAll()) {
35	            if (other.getCustomerCode() != null) {
36	                existing.add(other.getCustomerCode());
37	            }
38	        }
39	
40	        String customerCode = base;
41	        for (int n = 2; existing.contains(customerCode); n++) {
42	            customerCode = base + "-" + n;
43	        }
44	        owner.setCustomerCode(customerCode);
45	    }
46	}
47

