6	/**
7	 * Assigns the {@code membershipNumber} formatted {@code <customerCode>-M<YY>}, where YY is
8	 * the last two digits of the fiscal year (starting 1 July) of the owner's business-day-adjusted
9	 * {@code registrationDate} (e.g. {@code NSW-1A2B3C4D-M26}). Runs after {@link AssignCustomerCode}
10	 * and after the registration date has been defaulted and adjusted, so it carries the new
11	 * region-and-hash {@code customerCode}.
12	 */
13	public class AssignMembershipNumber {
14	
15	    public void service(@Val Owner owner) {
16	        int yy = FiscalYear.yy(owner.getRegistrationDate());
17	        owner.setMembershipNumber(String.format("%s-M%02d", owner.getCustomerCode(), yy));
18	    }
19	}
