1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Computes the Luhn {@code checkDigit} (0-9) over the decimal digits contained in an owner's
5	 * {@code customerCode}. Non-digit characters (the separating dash and the hex letters {@code A-F}
6	 * of the hash) are ignored, so the check digit is taken over the decimal digits of the
7	 * {@code <REGION>-<HASH8>} identity alone. Derived deterministically from the customer code, so it
8	 * is stable across requests and needs no persisted column.
9	 */
10	public final class CheckDigit {
11	
12	    private CheckDigit() {
13	    }
14	
15	    /** The Luhn check digit over the digits of {@code s}, or 0 when {@code s} is null. */
16	    public static int of(String s) {
17	        if (s == null) {
18	            return 0;
19	        }
20	        int sum = 0;
21	        boolean dbl = true;
22	        for (int i = s.length() - 1; i >= 0; i--) {
23	            char c = s.charAt(i);
24	            if (c < '0' || c > '9') {
25	                continue;
26	            }
27	            int d = c - '0';
28	            if (dbl) {
29	                d *= 2;
30	                if (d > 9) {
31	                    d -= 9;
32	                }
33	            }
34	            sum += d;
35	            dbl = !dbl;
36	        }
37	        return (10 - (sum % 10)) % 10;
38	    }
39	}
