3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year helper. The fiscal year starts on 1 July and is numbered by the calendar year it ends
7	 * in, so 1 July 2025 – 30 June 2026 is fiscal year 2026. Every date-derived value on an owner (the
8	 * membership-number year segment, the {@code fiscalYear} label and tenure) is measured on this
9	 * basis, always from the business-day-adjusted registration date.
10	 */
11	public final class FiscalYear {
12	
13	    private FiscalYear() {
14	    }
15	
16	    /** The fiscal year (starting 1 July) containing {@code date}, numbered by the year it ends in. */
17	    public static int of(LocalDate date) {
18	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
19	    }
20	
21	    /** The last two digits of the fiscal year of {@code date} (the {@code <YY>} identifier segment). */
22	    public static int yy(LocalDate date) {
23	        return of(date) % 100;
24	    }
25	
26	    /** The {@code 'FY<YY>'} label for {@code date}, or {@code null} when {@code date} is {@code null}. */
27	    public static String label(LocalDate date) {
28	        return date == null ? null : String.format("FY%02d", yy(date));
29	    }
30	
31	    /** Whole fiscal years elapsed from {@code from} to {@code to} (the number of 1 July boundaries crossed). */
32	    public static int elapsed(LocalDate from, LocalDate to) {
33	        return of(to) - of(from);
34	    }
35	}
