1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * SHA-256 of a string to its lower-case hex form — the one place the owner pipeline turns a value
9	 * into a digest. The derived keys differ only in how much of it they keep: {@link HouseholdId} and
10	 * {@link AssignCustomerCode} take a fixed-width, upper-case leading slice, while a full-width key
11	 * uses all 64 characters. Centralising the digest-and-hex step keeps every derived key hashing the
12	 * same way.
13	 */
14	final class Sha256 {
15	
16	    private Sha256() {
17	    }
18	
19	    /** The full lower-case hex SHA-256 (64 characters) of the UTF-8 bytes of {@code value}. */
20	    static String hex(String value) {
21	        try {
22	            byte[] digest = MessageDigest.getInstance("SHA-256")
23	                    .digest(value.getBytes(StandardCharsets.UTF_8));
24	            StringBuilder hex = new StringBuilder(digest.length * 2);
25	            for (byte b : digest) {
26	                hex.append(String.format("%02x", b));
27	            }
28	            return hex.toString();
29	        }
30	        catch (NoSuchAlgorithmException e) {
31	            throw new IllegalStateException("SHA-256 not available", e);
32	        }
33	    }
34	}
