1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Derives an owner's {@code identityKey}: the single value all duplicate detection is now expressed
7	 * through. It is the full lower-case hex {@link Sha256} of {@code normalizedTelephone + '|' +
8	 * lowerEmail + '|' + soundex(lastName)}, where the telephone is normalized to E.164 the same way as
9	 * {@link NormalizeTelephone}/{@link TelephoneE164}, the email is trimmed and lower-cased (empty when
10	 * absent or blank, the same form as {@link NormalizeEmail}), and the surname component is
11	 * {@link Soundex} of the last name. Because the telephone is part of the key, two members of the same
12	 * household — same {@code soundex(lastName)} and postcode but different telephones — derive different
13	 * identityKeys and are not a hard duplicate; the postcode is no longer part of the key, so it is the
14	 * soft-match ({@link DetectPossibleDuplicate}) that pairs such owners.
15	 */
16	public final class IdentityKey {
17	
18	    private IdentityKey() {
19	    }
20	
21	    public static String of(String telephone, String email, String lastName) {
22	        String normalizedTelephone = TelephoneE164.normalizeOrNull(telephone);
23	        if (normalizedTelephone == null) {
24	            normalizedTelephone = telephone == null ? "" : telephone.trim();
25	        }
26	        String normalizedEmail = (email == null || email.isBlank())
27	                ? "" : email.trim().toLowerCase(Locale.ROOT);
28	        String soundex = Soundex.of(lastName);
29	        return Sha256.hex(normalizedTelephone + "|" + normalizedEmail + "|" + soundex);
30	    }
31	}
