1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality}: the canonical region. The postcode is preferred — a postcode
7	 * that falls in a known range fixes the region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, via
8	 * {@link PostcodeRanges}) regardless of the city. Only when the postcode is absent or in no known
9	 * range does it fall back to the fixed city-to-region table (Sydney -> NSW, Melbourne -> VIC,
10	 * Brisbane -> QLD). Any city not in the table (including a null or blank city) derives
11	 * {@code "UNKNOWN"}. This returns the same region for known cities but disambiguates cities that
12	 * share a name. The mapping is pinned so it is stable across requests and needs no persisted column.
13	 */
14	public final class Locality {
15	
16	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
17	    private static final Map<String, String> CITY_REGION = Map.of(
18	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
19	
20	    static final String UNKNOWN = "UNKNOWN";
21	
22	    private Locality() {
23	    }
24	
25	    /** The region for {@code city} from the fixed table alone, or {@code "UNKNOWN"} when unlisted. */
26	    public static String of(String city) {
27	        return CITY_REGION.getOrDefault(city, UNKNOWN);
28	    }
29	
30	    /**
31	     * Derives the region, preferring the postcode: the region whose range contains the postcode wins;
32	     * otherwise the city-to-region table decides.
33	     */
34	    public static String of(String city, String postcode) {
35	        String fromPostcode = PostcodeRanges.regionFor(postcode);
36	        if (fromPostcode != null) {
37	            return fromPostcode;
38	        }
39	        return CITY_REGION.getOrDefault(city, UNKNOWN);
40	    }
41	
42	    /**
43	     * The locality read back off the owner's {@code customerCode} identity ({@code <REGION>-<HASH8>},
44	     * see {@link AssignCustomerCode}): the REGION segment before the first {@code '-'}. Returns
45	     * {@code "UNKNOWN"} when the code is null or carries no region segment, so locality now flows from
46	     * the same region-and-hash identity rather than being derived independently.
47	     */
48	    public static String ofCustomerCode(String customerCode) {
49	        if (customerCode == null) {
50	            return UNKNOWN;
51	        }
52	        int dash = customerCode.indexOf('-');
53	        if (dash <= 0) {
54	            return UNKNOWN;
55	        }
56	        return customerCode.substring(0, dash);
57	    }
58	}
