1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Fixed region-to-postcode-range table used to validate an owner's postcode against the region
7	 * derived from its city (see {@link Locality}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region
8	 * with no entry (including {@code "UNKNOWN"}) has no range, so any 4-digit postcode is accepted.
9	 */
10	public final class PostcodeRanges {
11	
12	    /** Region -> inclusive 4-digit postcode range {low, high}. */
13	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
14	            "NSW", new int[] {2000, 2099},
15	            "VIC", new int[] {3000, 3099},
16	            "QLD", new int[] {4000, 4099});
17	
18	    private PostcodeRanges() {
19	    }
20	
21	    /** The inclusive {low, high} range for {@code region}, or {@code null} when the region is unknown. */
22	    public static int[] forRegion(String region) {
23	        return REGION_POSTCODES.get(region);
24	    }
25	
26	    /**
27	     * The region whose range contains {@code postcode}, or {@code null} when the postcode is absent,
28	     * not four digits, or in no known range.
29	     */
30	    public static String regionFor(String postcode) {
31	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
32	            return null;
33	        }
34	        int value = Integer.parseInt(postcode);
35	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
36	            int[] range = entry.getValue();
37	            if (value >= range[0] && value <= range[1]) {
38	                return entry.getKey();
39	            }
40	        }
41	        return null;
42	    }
43	}
