1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	
5	/**
6	 * Derives an owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>} and always one of
7	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
8	 * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when {@code membershipLevel} is 3 or more,
9	 * otherwise {@code STANDARD}. AREA is {@code METRO} when the locality is a known region
10	 * (NSW, VIC or QLD, see {@link Locality}), otherwise {@code REGIONAL}. Pinned and stable across
11	 * requests, so it needs no persisted column.
12	 */
13	public final class OwnerSegment {
14	
15	    /** Membership level at or above which the owner is in the PREMIUM tier. */
16	    private static final int PREMIUM_THRESHOLD = 3;
17	
18	    /** Regions treated as METRO; anything else (including "UNKNOWN") is REGIONAL. */
19	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
20	
21	    private OwnerSegment() {
22	    }
23	
24	    /** The segment for the given {@code locality} region and {@code membershipLevel}. */
25	    public static String of(String locality, Integer membershipLevel) {
26	        String tier = membershipLevel != null && membershipLevel >= PREMIUM_THRESHOLD ? "PREMIUM" : "STANDARD";
27	        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
28	        return tier + "_" + area;
29	    }
30	}
