3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	import tools.jackson.databind.json.JsonMapper;
11	
12	/**
13	 * Emits audit side-effects to the dedicated {@code AUDIT} logger on successful create:
14	 * <ol>
15	 * <li>a human-readable audit line carrying the newly assigned owner id, the customerCode, the
16	 * registrationDate, the membershipLevel and the membershipNumber; and</li>
17	 * <li>an immutable structured {@link OwnerCreatedEvent} serialized as JSON, carrying a
18	 * monotonically increasing {@code seq}, the owner id, the current primary identifier and the
19	 * membershipLevel.</li>
20	 * </ol>
21	 */
22	public class AuditOwnerCreated {
23	
24	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
25	
26	    /** Monotonically increasing sequence, shared across every create. */
27	    private static final AtomicLong SEQ = new AtomicLong();
28	
29	    private static final JsonMapper JSON = JsonMapper.builder().build();
30	
31	    public void service(@Val Owner owner) {
32	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
33	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
34	                owner.getMembershipLevel(), owner.getMembershipNumber());
35	
36	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
37	                primaryIdentifier(owner), owner.getMembershipLevel(), OwnerCreatedEvent.OWNER_CREATED);
38	        AUDIT.info(JSON.writeValueAsString(event));
39	    }
40	
41	    /**
42	     * The owner's current primary identifier. Today the customerCode; when the customerCode is
43	     * unified into the memberId this becomes {@code owner.getMemberId()}, and the emitted event
44	     * carries the memberId with no other change.
45	     */
46	    private static String primaryIdentifier(Owner owner) {
47	        return owner.getCustomerCode();
48	    }
49	}
