1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Derives an owner's {@code householdId}: a stable identifier shared by every owner with the same
7	 * last name and postcode (one household). The last name is normalized (trim, collapse runs of
8	 * whitespace to a single space, lower-case) and joined to the postcode with a {@code '|'} separator
9	 * before hashing, so owners with the same last name and postcode — including one created with
10	 * {@code sharesHousehold} true, which by definition matches an existing owner's last name and
11	 * postcode — derive the identical value. Computed as the first 12 upper-case hex characters of
12	 * SHA-256 over {@code normalizedLastName + '|' + postcode}, so it is stable across requests and needs
13	 * no persisted column.
14	 */
15	public final class HouseholdId {
16	
17	    private HouseholdId() {
18	    }
19	
20	    public static String of(String lastName, String postcode) {
21	        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
22	        return Sha256.hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
23	    }
24	
25	    private static String normalize(String value) {
26	        if (value == null) {
27	            return "";
28	        }
29	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
30	    }
31	}
