1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Soft-match duplicate detection for create-owner. Runs after the identity duplicate block
12	 * ({@link RejectDuplicateOwner}), which rejects only an exact {@link IdentityKey} collision. A soft
13	 * match is the near-miss the identity key deliberately lets through: an owner whose identityKey
14	 * <em>differs</em> from an existing owner's yet shares that owner's {@code soundex(lastName)} and
15	 * postcode — for example two members of one household with different telephones (different telephone →
16	 * different identityKey). Such an owner is flagged: {@code possibleDuplicate} true and
17	 * {@code possibleDuplicateOf} the matching owner's id (the lowest id when several match).
18	 *
19	 * <p>A request that sets {@code sharesHousehold} true is a declared household member, not a suspected
20	 * duplicate, so it is never flagged: {@code possibleDuplicate} false and {@code possibleDuplicateOf}
21	 * null. Soft-deleted owners are ignored, as by the duplicate block. Runs before the owner is saved, so
22	 * {@link OwnerRepository#findAll()} sees only owners that existed before this create.
23	 */
24	public class DetectPossibleDuplicate {
25	
26	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            owner.setPossibleDuplicate(false);
29	            owner.setPossibleDuplicateOf(null);
30	            return; // declared household member — not a suspected duplicate
31	        }
32	        String soundex = Soundex.of(owner.getLastName());
33	        String identityKey = IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
34	        Owner match = null;
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (Boolean.TRUE.equals(existing.getDeleted())) {
37	                continue; // soft-deleted owners are ignored by the duplicate check
38	            }
39	            String existingKey = IdentityKey.of(existing.getTelephone(), existing.getEmail(),
40	                    existing.getLastName());
41	            if (identityKey.equals(existingKey)) {
42	                continue; // same identityKey is a hard duplicate (409), not a soft match
43	            }
44	            if (soundex.equals(Soundex.of(existing.getLastName()))
45	                    && Objects.equals(owner.getPostcode(), existing.getPostcode())) {
46	                if (match == null || existing.getId() < match.getId()) {
47	                    match = existing;
48	                }
49	            }
50	        }
51	        if (match != null) {
52	            owner.setPossibleDuplicate(true);
53	            owner.setPossibleDuplicateOf(match.getId());
54	        } else {
55	            owner.setPossibleDuplicate(false);
56	            owner.setPossibleDuplicateOf(null);
57	        }
58	    }
59	}
