5	/**
6	 * Maps an owner's {@code locality} (canonical region, see {@link Locality}) to its IANA timezone name
7	 * via a fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
8	 * QLD -> Australia/Brisbane). Any region not in the table (including {@code "UNKNOWN"} or null)
9	 * derives no timezone ({@code null}). The mapping is pinned so it is stable across requests and needs
10	 * no persisted column.
11	 */
12	public final class Timezone {
13	
14	    /** Region -> IANA timezone; anything not listed derives no timezone (null). */
15	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
16	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
17	
18	    private Timezone() {
19	    }
20	
21	    /** The IANA timezone for {@code region} from the fixed table, or {@code null} when unlisted. */
22	    public static String of(String region) {
23	        return REGION_TIMEZONE.get(region);
24	    }
25	}
